private async gatherFeatureData(featureId) {
  const featureWi = await this.client.getWorkItemWithRelations(featureId);
  const feature = {
    id: featureId,
    title: featureWi.fields['System.Title'] || `Feature #${featureId}`, // synthetic title if the field is blank, so downstream output never shows undefined
    description: featureWi.fields['System.Description'] || '',
  };

  const storyIds = await this.client.getStoryIdsByFeature(featureId);
  const stories = [];

  for (const storyId of storyIds.sort((a, b) => a - b)) { // numeric sort for stable ID order (JS default sort is lexicographic — '10' < '2')
    const wi = await this.client.getWorkItemWithRelations(storyId);
    const f = wi.fields || {};
    // count only the forward TestedBy links = the test cases THIS story owns
    const tcIds = this.client.extractRelationIds(
      wi.relations || [], 'Microsoft.VSTS.Common.TestedBy-Forward'
    );
    stories.push({
      id: storyId,
      title: f['System.Title'] || `Story #${storyId}`,
      priority: f['Microsoft.VSTS.Common.Priority'] || 2, // default P2 when unset — a middling weight, so an unprioritised story isn't top or bottom
      testCaseCount: tcIds.length, // the load unit the balancer distributes — just the count of TestedBy links, not the tests
    });
  }
  return { feature, stories };
}

private balanceWorkload(stories, teamNames) {
  const members = teamNames.map(name => ({
    name, stories: [], totalTCs: 0, weightedLoad: 0,
    p1Count: 0, p2Count: 0, p3Count: 0, dailyTarget: 0,
  }));

  // Greedy bin-packing works best largest-first: sort by priority (P1 first), then TC count descending
  const sorted = [...stories].sort((a, b) =>
    a.priority !== b.priority ? a.priority - b.priority : b.testCaseCount - a.testCaseCount // lower priority number = more urgent; tie-break on the heaviest story first
  );

  for (const story of sorted) {
    // assign this story to whoever currently has the lightest WEIGHTED load (not raw TC count)
    const target = members.reduce(
      (min, m) => (m.weightedLoad < min.weightedLoad ? m : min), members[0]
    );
    const weight = PRIORITY_WEIGHTS[story.priority] ?? 1.0; // e.g. P1=1.5, P4=0.3; ?? 1.0 guards an unknown priority so it never NaNs the load
    target.stories.push(story);
    target.totalTCs += story.testCaseCount;
    target.weightedLoad += story.testCaseCount * weight; // weighted load drives the next pick; totalTCs stays the raw count for reporting
  }
  return members;
}

private generateTimeline(startStr, endStr) {
  const totalDays = this.getBusinessDays(startStr, endStr); // weekends excluded — planning is in working days, not calendar days

  const executionDays = Math.min(4, totalDays - 2); // execution capped at 4 days; the -2 reserves at least a day each for creation & triage
  const triageDays = Math.min(4, totalDays - executionDays - 1); // triage also capped at 4, from whatever remains after execution
  const creationDays = Math.max(1, totalDays - executionDays - triageDays); // creation soaks up the remainder; Math.max(1, ...) guarantees a day even on a tiny sprint

  const creationEnd = this.addBusinessDays(startStr, creationDays - 1);
  const executionStart = this.addBusinessDays(creationEnd, 1); // +1 business day so the next phase starts the following working day, not on creationEnd itself
  const executionEnd = this.addBusinessDays(executionStart, executionDays - 1);
  const triageStart = this.addBusinessDays(executionEnd, 1);

  return {
    phases: [
      { name: 'TC Creation/Modification', startDate: startStr, endDate: creationEnd, businessDays: creationDays },
      { name: 'Test Execution', startDate: executionStart, endDate: executionEnd, businessDays: executionDays },
      { name: 'Bug Triage + Retest', startDate: triageStart, endDate: endStr, businessDays: triageDays },
    ],
    totalBusinessDays: totalDays,
  };
}

private generateMilestones(timeline, leadName) {
  const phases = timeline.phases;
  // Six checkpoints derived purely from phase boundaries — each phase's start/end, plus a mid-execution review
  return [
    { name: 'TC Creation Kickoff', date: phases[0].startDate, owner: leadName, status: 'Pending',
      description: 'Begin test case creation for all user stories' },
    { name: 'TC Creation Complete', date: phases[0].endDate, owner: leadName, status: 'Pending',
      description: 'All test cases written, reviewed, and uploaded' },
    { name: 'Execution Start', date: phases[1].startDate, owner: leadName, status: 'Pending',
      description: 'Begin test execution across all assigned stories' },
    { name: '50% Checkpoint',
      date: this.addBusinessDays(phases[1].startDate, Math.floor(phases[1].businessDays / 2)), // 50% checkpoint = execution start + half its business days (floored), i.e. the midpoint working day
      owner: leadName, status: 'Pending', description: 'Mid-sprint execution progress review' },
    { name: 'Execution Complete', date: phases[1].endDate, owner: leadName, status: 'Pending',
      description: 'All test cases executed, results logged' },
    { name: 'Sprint Sign-off', date: phases[2].endDate, owner: leadName, status: 'Pending',
      description: 'Bug triage complete, retest done, sprint sign-off' },
  ];
}

private generateRiskAssessment(team, timeline, stories) {
  const risks = [];
  const totalTCs = team.reduce((s, m) => s + m.totalTCs, 0);
  const tcsPerPerson = team.length > 0 ? totalTCs / team.length : 0; // guard divide-by-zero on an empty roster, which would otherwise be NaN and skip the check

  // Rule R-1: sustained load over ~50 TCs/person signals overload regardless of who it lands on
  if (tcsPerPerson > 50) {
    risks.push({
      id: 'R-1', category: 'Resource', severity: 'High',
      description: `High TC load: ${Math.round(tcsPerPerson)} TCs per person on average`,
      mitigation: 'Consider adding team members or reducing scope. Prioritize P1 stories first.',
    });
  }

  // Rule R-2: fewer than 10 business days is a schedule risk; how severe depends on how short
  if (timeline.totalBusinessDays < 10) {
    risks.push({
      id: 'R-2', category: 'Schedule',
      severity: timeline.totalBusinessDays < 7 ? 'High' : 'Medium', // graduated: under 7 days is High, 7-9 days Medium
      description: `Short sprint: only ${timeline.totalBusinessDays} business days`,
      mitigation: 'Prioritize P1/P2 stories. Defer P3 stories if needed.',
    });
  }
  return risks;
}

